"""Small closed diagnostic vocabulary; never serialize exception text or paths."""
import json
import subprocess

STAGES = frozenset((
    'scope.identity', 'scope.memory_max', 'scope.swap_max', 'scope.pids_max',
    'scope.oom_group', 'scope.cpu', 'scope.rlimit_cpu', 'scope.rlimit_file',
    'scope.rlimit_address', 'scope.rlimit_core', 'scope.priority',
    'scope.namespace.absent', 'scope.namespace.root', 'scope.namespace.var',
    'scope.namespace.proc', 'scope.namespace.sys', 'scope.namespace.run',
    'scope.namespace.systemd', 'scope.namespace.incoming',
    'scope.readonly.bin', 'scope.readonly.lib', 'scope.readonly.liblink',
    'scope.readonly.lib64', 'scope.readonly.limits', 'scope.temp',
    'scope.own_group', 'scope.resources',
    'controller.identity', 'controller.payload', 'controller.preflight',
    'controller.namespace', 'controller.marker', 'controller.unit_absent',
    'controller.interrupted', 'controller.output',
    'transport.launch', 'transport.pipe', 'transport.deadline',
    'transport.output_cap', 'transport.protocol', 'transport.exit', 'fixtures.suite',
    'cleanup.unit', 'cleanup.unit_stop', 'cleanup.unit_reset',
    'cleanup.cgroup', 'cleanup.mounts', 'cleanup.inventory',
    'cleanup.marker', 'cleanup.remove', 'cleanup.verify',
    'preflight.metadata', 'preflight.memory', 'preflight.controllers',
    'preflight.systemd', 'preflight.unit', 'preflight.identity',
    'preflight.healthz', 'preflight.readyz', 'preflight.disk',
    'preflight.pressure', 'preflight.paths',
))
ERRORS = frozenset((
    'MISMATCH', 'MALFORMED', 'UNEXPECTED_ENTRY', 'UNEXPECTED_TYPE',
    'WRONG_OWNER', 'NONEMPTY', 'ACCESSIBLE', 'WRITABLE',
    'MISSING', 'PERMISSION_DENIED', 'TIMEOUT', 'OUTPUT_CLOSED',
    'OUTPUT_CAP', 'OS_ERROR', 'MEMORY_ERROR', 'INTERRUPTED',
    'UNEXPECTED_EXCEPTION', 'PROTOCOL', 'NONZERO_EXIT', 'SUITE_FAILURE',
))

def valid_failure(value):
    return (type(value) is dict and set(value) == {'stage', 'error'}
            and type(value['stage']) is str and value['stage'] in STAGES
            and type(value['error']) is str and value['error'] in ERRORS)

class GateError(Exception):
    def __init__(self, stage, error):
        if stage not in STAGES or error not in ERRORS:
            raise ValueError('CLOSED_DIAGNOSTIC_VOCABULARY')
        self.failure = {'stage': stage, 'error': error}
        super().__init__('SANITIZED_GATE')

class Stage:
    def __init__(self, name):
        self.at(name)
    def at(self, name):
        if name not in STAGES:
            raise ValueError('CLOSED_DIAGNOSTIC_VOCABULARY')
        self.name = name
        return self
    def need(self, condition, error='MISMATCH'):
        if not condition:
            raise GateError(self.name, error)

def sanitized(exc, stage):
    if type(exc) is GateError and valid_failure(exc.failure):
        return dict(exc.failure)
    error = 'UNEXPECTED_EXCEPTION'
    for cls, code in ((PermissionError, 'PERMISSION_DENIED'),
                      (FileNotFoundError, 'MISSING'),
                      (BrokenPipeError, 'OUTPUT_CLOSED'),
                      (subprocess.TimeoutExpired, 'TIMEOUT'),
                      (MemoryError, 'MEMORY_ERROR'),
                      (KeyboardInterrupt, 'INTERRUPTED'),
                      (OSError, 'OS_ERROR'),
                      (ValueError, 'MALFORMED')):
        if isinstance(exc, cls):
            error = code
            break
    name = stage.name if isinstance(stage, Stage) else stage
    if name not in STAGES:
        name = 'controller.output'
    return {'stage': name, 'error': error}

def encode(body, maximum=15000):
    value = json.dumps(body, sort_keys=True, allow_nan=False)
    if len(value.encode()) > maximum:
        raise GateError('controller.output', 'OUTPUT_CAP')
    return value

"""Bounded facts from frozen synthetic tests, never exception text or values."""
import json
import os
import platform
import sqlite3
import sys
import unittest

TYPE_NAMES = ('NoneType', 'bool', 'int', 'float', 'str', 'bytes', 'list', 'tuple', 'dict', 'set', 'type', 'OTHER', 'NOT_CAPTURED')
EXCEPTIONS = ('AssertionError', 'TypeError', 'ValueError', 'RuntimeError', 'OSError', 'PermissionError', 'FileNotFoundError', 'MemoryError', 'RecursionError', 'OperationalError', 'DatabaseError', 'IntegrityError', 'OTHER', 'NOT_CAPTURED')
ASSERTIONS = ('assertEqual', '_baseAssertEqual', 'assertIsInstance', 'assertTrue', 'assertFalse')
UNIT_FUNCTIONS = ASSERTIONS + ('fail', '_callTestMethod', '_callSetUp', '_callTearDown', 'run', 'testPartExecutor', '_raiseFailure', '__exit__', 'assertRaises', 'assertRaisesRegex')
MAX_FAILURES = 6
MAX_FRAMES = 5
# Compact keys cover later errors without raising any transport/resource cap.
MAX_CASE_RECORDS = 124
OUTCOMES = ('failure', 'error', 'subtest_failure', 'subtest_error', 'unexpected_success')
REASONS = ('EXCEPTION_CATEGORY', 'ASSERTION_FAILED', 'EQUALITY_TYPES_DIFFER',
           'EQUALITY_VALUES_DIFFER', 'INSTANCE_CHECK_FAILED', 'TRUTH_CHECK_FAILED',
           'EXPECTED_EXCEPTION_ASSERTION_FAILED', 'UNEXPECTED_SUCCESS')
def assertion_reason(detail):
    if detail['outcome'] == 'unexpected_success':
        return 'UNEXPECTED_SUCCESS'
    if detail['exception'] != 'AssertionError':
        return 'EXCEPTION_CATEGORY'
    semantics = detail['type_semantics']
    if semantics == 'first_second_operands':
        return ('EQUALITY_TYPES_DIFFER' if detail['actual_type'] != detail['expected_type']
                else 'EQUALITY_VALUES_DIFFER')
    if semantics == 'instance_check':
        return 'INSTANCE_CHECK_FAILED'
    if semantics == 'truth_check':
        return 'TRUTH_CHECK_FAILED'
    if any(frame['file'] == 'unittest' and frame['function'] in
           ('assertRaises', 'assertRaisesRegex', '__exit__')
           for frame in detail['stack']):
        return 'EXPECTED_EXCEPTION_ASSERTION_FAILED'
    return 'ASSERTION_FAILED'
def record_key(detail, policy):
    case = policy['cases'].index(detail['case']) if detail['case'] in policy['cases'] else -1
    return (case, OUTCOMES.index(detail['outcome']), EXCEPTIONS.index(detail['exception']),
            REASONS.index(assertion_reason(detail)))

def type_name(value):
    for cls in (type(None), bool, int, float, str, bytes, list, tuple, dict, set, type):
        if type(value) is cls:
            return cls.__name__
    return 'OTHER'

def class_name(value):
    for cls in (type(None), bool, int, float, str, bytes, list, tuple, dict, set, type):
        if value is cls:
            return cls.__name__
    return 'OTHER'

def exception_name(value):
    for cls in (AssertionError, TypeError, ValueError, RuntimeError, OSError, PermissionError, FileNotFoundError, MemoryError, RecursionError,
                sqlite3.OperationalError, sqlite3.DatabaseError, sqlite3.IntegrityError):
        if value is cls:
            return cls.__name__
    return 'OTHER'

class FactsResult(unittest.TestResult):
    def __init__(self, policy):
        super().__init__()
        self.policy = policy
        self.facts = []
        self.case_records = {}
        self.case_records_omitted = 0
        self.issue_count = 0
        self.unrecognized_cases = 0
        self.failure_count = self.error_count = self.unexpected_count = 0

    def _exc_info_to_string(self, err, test):
        # unittest must not render exception values, source lines or locals.
        return 'SANITIZED_SYNTHETIC_FAILURE'

    def record(self, test, outcome, err=None):
        self.issue_count += 1
        case = getattr(test, 'test_case', test)
        identifier = case.__class__.__module__ + '.' + case.__class__.__name__ + '.' + getattr(case, '_testMethodName', '')
        if identifier not in self.policy['cases']:
            self.unrecognized_cases += 1
            identifier = 'UNRECOGNIZED_CASE'
        facts = dict(case=identifier, outcome=outcome, exception='NOT_CAPTURED',
                     actual_type='NOT_CAPTURED', expected_type='NOT_CAPTURED',
                     type_semantics='not_captured', stack=[], omitted_frames=0)
        if err:
            facts['exception'] = exception_name(err[0])
            tb = err[2]
            frames = []
            while tb:
                code = tb.tb_frame.f_code
                file, function = code.co_filename, code.co_name
                spec = self.policy['files'].get(file)
                if spec and (function in spec['functions'] or function == '<module>') and 0 < tb.tb_lineno <= spec['lines']:
                    frames.append(dict(file=file, function=function, line=tb.tb_lineno))
                elif file.startswith(os.path.dirname(unittest.__file__) + os.sep) and function in UNIT_FUNCTIONS:
                    frames.append(dict(file='unittest', function=function, line=tb.tb_lineno))
                else:
                    facts['omitted_frames'] += 1
                # Read only fixed assertion operands' types. Never repr/value.
                if file.startswith(os.path.dirname(unittest.__file__) + os.sep):
                    operands = tb.tb_frame.f_locals
                    if function in ('assertEqual', '_baseAssertEqual'):
                        facts.update(actual_type=type_name(operands.get('first')), expected_type=type_name(operands.get('second')), type_semantics='first_second_operands')
                    elif function == 'assertIsInstance':
                        facts.update(actual_type=type_name(operands.get('obj')), expected_type=class_name(operands.get('cls')), type_semantics='instance_check')
                    elif function in ('assertTrue', 'assertFalse'):
                        facts.update(actual_type=type_name(operands.get('expr')), expected_type='bool', type_semantics='truth_check')
                tb = tb.tb_next
            facts['omitted_frames'] += max(0, len(frames) - MAX_FRAMES)
            facts['stack'] = frames[-MAX_FRAMES:]
        key = record_key(facts, self.policy)
        if key in self.case_records:
            self.case_records[key] += 1
        elif len(self.case_records) < MAX_CASE_RECORDS:
            self.case_records[key] = 1
        else:
            self.case_records_omitted += 1
        if len(self.facts) < MAX_FAILURES:
            self.facts.append(facts)

    def addFailure(self, test, err):
        self.failure_count += 1
        self.record(test, 'failure', err)
        super().addFailure(test, err)

    def addError(self, test, err):
        self.error_count += 1
        self.record(test, 'error', err)
        super().addError(test, err)

    def addSubTest(self, test, subtest, err):
        if err:
            failure = issubclass(err[0], test.failureException)
            self.failure_count += int(failure)
            self.error_count += int(not failure)
            self.record(test, 'subtest_failure' if failure else 'subtest_error', err)
        super().addSubTest(test, subtest, err)

    def addUnexpectedSuccess(self, test):
        self.unexpected_count += 1
        self.record(test, 'unexpected_success')
        super().addUnexpectedSuccess(test)

    def summary(self):
        return dict(run=self.testsRun, failures=self.failure_count, errors=self.error_count,
                    skipped=len(self.skipped), expected_failures=len(self.expectedFailures),
                    unexpected_successes=self.unexpected_count, issue_count=self.issue_count,
                    unrecognized_cases=self.unrecognized_cases, details=self.facts,
                    details_omitted=self.issue_count-len(self.facts),
                    case_records=[list(key) + [count] for key, count in self.case_records.items()],
                    case_records_omitted=self.case_records_omitted)

def run_suites(test_pairs, policy):
    import types
    groups = []
    for name, source in test_pairs:
        module = types.ModuleType(name)
        exec(compile(source, name + '.py', 'exec'), module.__dict__)
        suite = unittest.defaultTestLoader.loadTestsFromModule(module)
        result = FactsResult(policy)
        suite.run(result)
        groups.append(result.summary())
    counts = [g['run'] for g in groups]
    ok = all(not g['issue_count'] for g in groups)
    machine = platform.machine()
    architecture = machine if machine in ('x86_64', 'aarch64', 'arm64') else 'OTHER'
    body = dict(counts=counts, ok=ok, groups=groups, runtime=dict(Python=sys.version.split()[0], SQLite=sqlite3.sqlite_version,
                platform=sys.platform if sys.platform in ('linux', 'darwin') else 'OTHER', architecture=architecture))
    # Keep a single event within the unchanged8192-byte transport line limit.
    while len(json.dumps(body).encode()) > 7600:
        detailed = [group for group in groups if group['details']]
        if detailed:
            group = max(detailed, key=lambda g:len(g['details']))
            group['details'].pop()
            group['details_omitted'] += 1
        else:
            group = max(groups, key=lambda g:len(g['case_records']))
            record = group['case_records'].pop()
            group['case_records_omitted'] += record[4]
    return body

def validate_facts(body, policy):
    """Closed consumer schema shared by the transport and terminal writer."""
    def need(ok):
        if not ok:
            raise ValueError('UNIT_DIAGNOSTIC_SCHEMA')
    def integer(n, high=1000):
        return type(n) is int and 0 <= n <= high
    need(type(body) is dict and set(body) == {'counts', 'ok', 'groups', 'runtime'})
    need(type(body['counts']) is list and len(body['counts']) == 2 and all(integer(x) for x in body['counts']))
    need(type(body['ok']) is bool and type(body['groups']) is list and len(body['groups']) == 2)
    runtime = body['runtime']
    need(type(runtime) is dict and set(runtime) == {'Python', 'SQLite', 'platform', 'architecture'})
    for key in ('Python', 'SQLite'):
        value = runtime[key]
        need(type(value) is str and len(value) <= 24 and len(value.split('.')) == 3 and all(x.isascii() and x.isdigit() and 0 < len(x) <= 5 for x in value.split('.')))
    need(runtime['platform'] in ('linux', 'darwin', 'OTHER') and runtime['architecture'] in ('x86_64', 'aarch64', 'arm64', 'OTHER'))
    for index, group in enumerate(body['groups']):
        numeric = {'run', 'failures', 'errors', 'skipped', 'expected_failures', 'unexpected_successes', 'issue_count', 'unrecognized_cases', 'details_omitted', 'case_records_omitted'}
        need(type(group) is dict and set(group) == numeric | {'details', 'case_records'} and all(integer(group[x]) for x in numeric))
        need(group['run'] == body['counts'][index] and group['issue_count'] == group['failures'] + group['errors'] + group['unexpected_successes'])
        need(type(group['details']) is list and len(group['details']) <= MAX_FAILURES and group['issue_count'] == len(group['details']) + group['details_omitted'] and group['unrecognized_cases'] <= group['issue_count'])
        records = group['case_records']
        need(type(records) is list and len(records) <= MAX_CASE_RECORDS)
        keys = set()
        totals = [0, 0, 0]
        unknown = 0
        counts_by_key = {}
        for record in records:
            need(type(record) is list and len(record) == 5 and
                 all(type(value) is int for value in record))
            case, outcome, exception, reason, count = record
            need(-1 <= case < len(policy['cases']) and 0 <= outcome < len(OUTCOMES)
                 and 0 <= exception < len(EXCEPTIONS) and 0 <= reason < len(REASONS)
                 and 1 <= count <= 1000)
            need(case == -1 or policy['cases'][case].startswith(('frame_tests.', 'reader_tests.')[index]))
            key = tuple(record[:4])
            need(key not in keys)
            keys.add(key)
            counts_by_key[key] = count
            totals[0 if outcome in (0, 2) else 1 if outcome in (1, 3) else 2] += count
            unknown += count if case == -1 else 0
            need((reason == REASONS.index('UNEXPECTED_SUCCESS')) == (outcome == 4))
            if outcome == 4:
                need(exception == EXCEPTIONS.index('NOT_CAPTURED'))
            else:
                need((reason == REASONS.index('EXCEPTION_CATEGORY')) ==
                     (exception != EXCEPTIONS.index('AssertionError')))
        reported = sum(record[4] for record in records)
        need(reported + group['case_records_omitted'] == group['issue_count'])
        expected = [group['failures'], group['errors'], group['unexpected_successes']]
        need(all(actual <= wanted for actual, wanted in zip(totals, expected))
             and unknown <= group['unrecognized_cases']
             and group['unrecognized_cases'] - unknown <= group['case_records_omitted'])
        if not group['case_records_omitted']:
            need(totals == expected and unknown == group['unrecognized_cases'])
        detail_counts = {}
        for detail in group['details']:
            need(type(detail) is dict and set(detail) == {'case', 'outcome', 'exception', 'actual_type', 'expected_type', 'type_semantics', 'stack', 'omitted_frames'})
            need((detail['case'] in policy['cases'] and detail['case'].startswith(('frame_tests.', 'reader_tests.')[index])) or detail['case'] == 'UNRECOGNIZED_CASE')
            need(detail['outcome'] in ('failure', 'error', 'subtest_failure', 'subtest_error', 'unexpected_success'))
            need(detail['exception'] in EXCEPTIONS and detail['actual_type'] in TYPE_NAMES and detail['expected_type'] in TYPE_NAMES)
            need(detail['type_semantics'] in ('not_captured', 'first_second_operands', 'instance_check', 'truth_check') and integer(detail['omitted_frames'], 10000))
            need(type(detail['stack']) is list and len(detail['stack']) <= MAX_FRAMES)
            for frame in detail['stack']:
                need(type(frame) is dict and set(frame) == {'file', 'function', 'line'} and integer(frame['line'], 100000) and frame['line'] > 0)
                spec = policy['files'].get(frame['file'])
                need((frame['file'] == 'unittest' and frame['function'] in UNIT_FUNCTIONS) or (spec and (frame['function'] in spec['functions'] or frame['function'] == '<module>') and frame['line'] <= spec['lines']))
            key = record_key(detail, policy)
            detail_counts[key] = detail_counts.get(key, 0) + 1
        need(all(count <= counts_by_key.get(key, 0) for key, count in detail_counts.items()))
        need(sum(d['outcome'] in ('failure', 'subtest_failure') for d in group['details']) <= group['failures'])
        need(sum(d['outcome'] in ('error', 'subtest_error') for d in group['details']) <= group['errors'])
        need(sum(d['outcome'] == 'unexpected_success' for d in group['details']) <= group['unexpected_successes'])
    need(body['ok'] == all(not g['issue_count'] for g in body['groups']))
    need(len(json.dumps(body).encode()) < 8000)
    return body
