"""Proposal-only disposable hosted-runner metadata; no cloud/health/data calls."""
import os
import pathlib
import platform
import pwd
import sqlite3
import subprocess
import sys

def bounded_metadata(path, maximum):
    with open(path, 'rb') as stream:
        value = stream.read(maximum + 1)
    if len(value) > maximum:
        raise ValueError('FIXED_METADATA_CAP')
    return value.decode('ascii')

def check(stage):
    # The proposed workflow remains disabled, and the assembled controller
    # refuses entry. A separately reviewed execution join must bind the exact
    # repository/commit/run-attempt and confirmed allowance before this check.
    stage.at('preflight.identity')
    stage.need(sys.platform == 'linux' and os.geteuid() == 0)
    stage.need(pwd.getpwnam('nobody').pw_uid == 65534)
    stage.at('preflight.metadata')
    stage.need(platform.machine() == 'x86_64')
    stage.need(sys.version.split()[0] == '3.11.2' and sqlite3.sqlite_version == '3.40.1')
    stage.at('preflight.systemd')
    result = subprocess.run(['/usr/bin/systemctl', '--version'],
                            stdin=subprocess.DEVNULL, capture_output=True, timeout=3,
                            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(result.returncode == 0, 'NONZERO_EXIT')
    stage.need(len(result.stdout) + len(result.stderr) <= 4096, 'OUTPUT_CAP')
    rows = result.stdout.decode('ascii').splitlines()
    stage.need(bool(rows) and len(rows[0].split()) >= 2, 'MALFORMED')
    version = rows[0].split()[1]
    stage.need(version.isascii() and version.isdigit() and len(version) <= 5, 'MALFORMED')
    stage.need(version == '252')
    manager = subprocess.run(['/usr/bin/systemctl', 'show', '--property=Version', '--value'],
                             stdin=subprocess.DEVNULL, capture_output=True, timeout=3,
                             env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(manager.returncode == 0, 'NONZERO_EXIT')
    stage.need(len(manager.stdout) + len(manager.stderr) <= 4096, 'OUTPUT_CAP')
    stage.need(manager.stdout.strip().split(b'.')[0] == b'252')
    stage.need(os.readlink('/proc/1/exe') in ('/usr/lib/systemd/systemd', '/lib/systemd/systemd'))
    readiness = subprocess.run(['/usr/bin/systemctl', 'is-system-running'],
                               stdin=subprocess.DEVNULL, capture_output=True, timeout=3,
                               env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(len(readiness.stdout) + len(readiness.stderr) <= 4096, 'OUTPUT_CAP')
    stage.need(readiness.returncode == 0 and readiness.stdout.strip() == b'running')
    stage.at('preflight.controllers')
    controllers = bounded_metadata('/sys/fs/cgroup/cgroup.controllers', 256).split()
    stage.need({'cpu', 'memory', 'pids'} <= set(controllers))
    stage.at('preflight.memory')
    memory = [line.split() for line in bounded_metadata('/proc/meminfo', 32768).splitlines()
              if line.startswith('MemAvailable:')]
    stage.need(len(memory) == 1 and len(memory[0]) == 3 and memory[0][2] == 'kB', 'MALFORMED')
    stage.need(memory[0][1].isdigit(), 'MALFORMED')
    stage.need(int(memory[0][1]) * 1024 >= 8589934592)
    stage.at('preflight.pressure')
    for path, kind, maximum in (('/proc/pressure/memory', 'full', 1),
                                ('/proc/pressure/io', 'some', 5)):
        rows = [line for line in bounded_metadata(path, 1024).splitlines()
                if line.startswith(kind + ' ')]
        stage.need(len(rows) == 1, 'MALFORMED')
        values = [field[6:] for field in rows[0].split() if field.startswith('avg10=')]
        stage.need(len(values) == 1, 'MALFORMED')
        value = float(values[0])
        stage.need(0 <= value <= 100, 'MALFORMED')
        stage.need(value < maximum)
    stage.at('preflight.paths')
    stage.need(all(pathlib.Path(path).exists() for path in (
        '/usr/bin/python3', '/usr/bin/systemd-run', '/usr/bin/systemctl',
        '/usr/bin', '/usr/lib', '/lib', '/lib64', '/etc/ld.so.cache')))
    stage.need(not pathlib.Path(PREFIX).exists() and not pathlib.Path(PREFIX).is_symlink())
    stage.at('preflight.unit')
    state = selected_unit(stage)
    stage.need(state.get('LoadState') == 'not-found'
               and state.get('MainPID', '0') == '0')
    # Emit fixed verified facts only, never raw metadata/command/error bodies.
    return {'admitted': True, 'scope': 'DISPOSABLE_HOSTED_DEBIAN12_SYNTHETIC_ONLY',
            'exact_runtime': {'Python': '3.11.2', 'SQLite': '3.40.1',
                              'systemd': '252', 'architecture': 'x86_64'},
            'fixtures_started': False, 'production_data_access': False}

