def publish(body):
    try:
        print(encode(body), flush=True)
        return True
    except (BrokenPipeError, OSError):
        return False  # Cleanup must still run after an output disconnect.
    except BaseException as exc:
        failure = sanitized(exc, 'controller.output')
        raise GateError(failure['stage'], failure['error']) from None

def selected_unit(stage):
    r = subprocess.run(['/usr/bin/systemctl', 'show', UNIT,
                        '--property=LoadState,ActiveState,SubState,Transient,RootDirectory,MainPID,Result,ExecMainStatus'],
                       stdin=subprocess.DEVNULL, capture_output=True, timeout=4)
    stage.need(r.returncode == 0, 'NONZERO_EXIT')
    stage.need(len(r.stdout) + len(r.stderr) <= 4096, 'OUTPUT_CAP')
    rows = r.stdout.decode('ascii').splitlines()
    stage.need(all('=' in x for x in rows), 'MALFORMED')
    value = dict(x.split('=', 1) for x in rows)
    stage.need(len(value) == len(rows), 'MALFORMED')
    return value

def parse_child(raw):
    """Keep a valid first failure even if a later line violates the protocol."""
    stage = Stage('transport.protocol')
    events = []
    first = protocol = None
    kinds = []
    try:
        for line in raw.splitlines():
            stage.need(len(line) <= 8192 and len(events) < 3, 'OUTPUT_CAP')
            body = json.loads(line)
            stage.need(type(body) is dict, 'PROTOCOL')
            kind = body.get('kind', body.get('scope'))
            if kind == 'synthetic_setup_hold':
                stage.need(set(body) == {'kind', 'fixtures_started', 'failure'}
                           and body['fixtures_started'] is False
                           and valid_failure(body['failure'])
                           and body['failure']['stage'].startswith('scope.')
                           and not kinds, 'PROTOCOL')
                first = dict(body['failure'])
            elif kind == 'synthetic_scope_verified':
                expected = {'kind': 'synthetic_scope_verified', 'unprivileged': True,
                           'memory_max_bytes': 134217728, 'swap_max_bytes': 0,
                           'CPU_quota_at_most_one_core': True, 'private_temp_max_bytes': 16777216,
                           'live_data_access_blocked': True}
                stage.need(body == expected and all(type(body[k]) is type(v)
                           for k, v in expected.items()) and not kinds, 'PROTOCOL')
            elif kind == 'LINUX_SYNTHETIC_UNIT_SUITE_ONLY':
                stage.need(set(body) == {'scope', 'native_admission', 'facts'}
                           and body['native_admission'] is False
                           and kinds == ['synthetic_scope_verified'], 'PROTOCOL')
                validate_facts(body['facts'], POLICY)
                stage.need(body['facts']['counts'] == [29, 95]
                           and all(g['skipped'] == 0 and g['expected_failures'] == 0
                                   for g in body['facts']['groups']), 'PROTOCOL')
                if not body['facts']['ok']:
                    first = first or {'stage': 'fixtures.suite', 'error': 'SUITE_FAILURE'}
            elif kind in ('synthetic_own_resources', 'synthetic_resource_hold'):
                stage.need(kinds == ['synthetic_scope_verified', 'LINUX_SYNTHETIC_UNIT_SUITE_ONLY'], 'PROTOCOL')
                if kind == 'synthetic_resource_hold':
                    stage.need(set(body) == {'kind', 'failure'} and valid_failure(body['failure'])
                               and body['failure']['stage'] == 'scope.resources', 'PROTOCOL')
                    first = first or dict(body['failure'])
                else:
                    stage.need(set(body) == {'kind', 'peak_RSS_bytes', 'user_CPU_seconds',
                               'system_CPU_seconds', 'elapsed_after_scope_seconds'}, 'PROTOCOL')
                    stage.need(type(body['peak_RSS_bytes']) is int
                               and 0 <= body['peak_RSS_bytes'] <= 134217728, 'PROTOCOL')
                    stage.need(all(type(body[x]) in (int, float) and 0 <= body[x] <= 15
                                   for x in ('user_CPU_seconds', 'system_CPU_seconds',
                                             'elapsed_after_scope_seconds')), 'PROTOCOL')
            else:
                raise GateError(stage.name, 'PROTOCOL')
            events.append(body)
            kinds.append(kind)
        stage.need(kinds == ['synthetic_setup_hold'] or kinds == [
                   'synthetic_scope_verified', 'LINUX_SYNTHETIC_UNIT_SUITE_ONLY',
                   'synthetic_own_resources'] or kinds == [
                   'synthetic_scope_verified', 'LINUX_SYNTHETIC_UNIT_SUITE_ONLY',
                   'synthetic_resource_hold'], 'PROTOCOL')
    except BaseException as exc:
        protocol = sanitized(exc, stage)
    return {'events': events, 'first_failure': first or protocol,
            'protocol_failure': protocol}

